SELECT user_id, post_type, post_id, created_at FROM saved_posts WHERE user_id = #{userId}
AND (created_at, post_type, post_id) > (#{afterCreatedAt}, #{afterPostType}, #{afterPostId})
AND (created_at, post_type, post_id) < (#{afterCreatedAt}, #{afterPostType}, #{afterPostId})
ORDER BY created_at ASC, post_type ASC, post_id ASC
ORDER BY created_at DESC, post_type DESC, post_id DESC
LIMIT #{limit}

SELECT post_id FROM saved_posts
WHERE user_id = #{userId} AND post_type = #{postType} AND post_id IN
#{id}
